style.css:
@-moz-document domain("dafont.com") {
:root { color-scheme: dark !important; }

  /* Base surfaces */
  html, body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }
  /* 404 page only: a bright photo as a `body` background-image. */
  body { background-image: none !important; }
  /* `.contain` is the pink per-row badge, not a wrapper: blanking it drops black glyphs
     onto the red bar. */
  .layout, .container, .width, .minwidth, .out,
  #content, table, tbody, tr, td {
    background-color: transparent !important;
  }

  /* Soften default light/black borders */
  * { border-color: #2d333b !important; }
  /* Invisible spacers on the white page; the author banner spells it `solid white`, so
     match both serialisations. */
  div[style*="solid #fff"], div[style*="solid white"] {
    border-color: transparent !important;
  }
  /* Same trick as text: a `color:#fff` shim dot on `search.php?q=` pages. The site's only
     inline white text, so the shape can stay unscoped. */
  span[style*="color:#fff"] { color: transparent !important; }
  /* The reset also greys every brand-red border the site draws — a lost signal. */
  #menuthemes table, .menupselect,
  .titlebar, h1, h3.headerpage, .headindex, .select, .new_date,
  .help {
    border-color: #b3322f !important;
  }
  /* Reply state is an inline border-color (#d4d4d4 none / #fc3 replies / #3d6 answered)
     echoed by the .square legend — keep the chromatic two verbatim. `requests.php` uses
     `div.thumb` for the same key. */
  div.thumb_cont[style*="#fc3"], div.thumb[style*="#fc3"] { border-color: #fc3 !important; }
  div.thumb_cont[style*="#3d6"], div.thumb[style*="#3d6"] { border-color: #3d6 !important; }
  /* Same key inline on "Identified font:" / "Suggested font:" callouts. NOT `div[…]`:
     `/forum/user.php?user=` draws both as a <span>. */
  [style*="solid #3d6"] { border-color: #3d6 !important; }
  [style*="solid #fc3"] { border-color: #fc3 !important; }
  /* Framed `10px solid #cc0000` inline, in both case spellings; that red edge is its whole
     emphasis. */
  div[style*="solid #cc0000"], div[style*="solid #CC0000"] {
    border-color: #b3322f !important;
  }
  /* .square repeats those hues as a BACKGROUND, not a border, so the reset misses them. */
  span.square[style*="#d4d4d4"] { background-color: #2d333b !important; }
  /* The chips encode "you are here" purely in the border: `.curgroup{solid #ccc}` vs
     `.othgroup{solid #fff}`, an invisible spacer. */
  .othgroup { border-color: transparent !important; }
  .curgroup { border-color: #8b949e !important; }

  /* Links */
  a { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }
  /* Many black-text links (font names, nav) need lifting. */
  a.tdn, a.tdn.black, .lv2right a, .noindex a, .menu a, .catpp a,
  .headindex a, .dfsmall a, .donate a, .fleche a {
    color: #5fb0e6 !important;
  }
  a.tdn:hover, .lv2right a:hover, .noindex a:hover, .menu a:hover,
  .catpp a:hover, .dfsmall a:hover { color: #9bd4ff !important; }
  /* `a.flag` is `color:#000; opacity:.60` and carries `.tdn`, so the link colours above
     would give 3.5:1 at 60% alpha. Must sit after `a:hover` to win the 0,1,1 tie. */
  a.flag, a.flag:hover { color: #c4cdd6 !important; }

  /* Brand red, refined for dark */
  /* Raw #cc0000 is garish on near-black; soften but keep the identity. */
  .dfbg, .lv1left, .lv1right, .lv2left {
    background-color: #b3322f !important;
    color: #ffffff !important;
    border-color: #8f2724 !important;
  }
  .dfbg a, .lv1left a, .lv1right a { color: #ffffff !important; }
  .headindex, .headindex a { color: #e86a64 !important; }
  /* "100% Free" red accent text */
  a[style*="color:#c00"], a[style*="color:#C00"] { color: #e86a64 !important; }

  /* Logo block keeps brand red */
  .logo, td.dfbg { background-color: #b3322f !important; }

  /* Top menu / category navigation */
  .menu { background-color: transparent !important; }
  #menuthemes, .colthemes { background-color: transparent !important; }
  .metacat, .metacat.dfbg {
    background-color: #b3322f !important;
    color: #ffffff !important;
  }
  /* This bar also carries .dfsmall, so the `.dfsmall` muted rules below must never
     out-specify (0,1,1) / (0,2,1). */
  .metacat a, .metacat.dfsmall a { color: #ffffff !important; }
  .catpp { background-color: transparent !important; color: #c4cdd6 !important; }
  /* `.catpp a:hover` hardcodes a light #e3e3e3 pill; our label on it reads ~1.5:1. */
  .catpp a:hover { background-color: #21262d !important; }
  /* The only `#menuthemes b` is the current subcategory, red as its "you are here" cue.
     Scoped to .catpp so .metacat headers keep the white set at the end of this sheet. */
  .catpp b { color: #e86a64 !important; }

  /* Search form + submit */
  .search_form, input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  ::placeholder { color: #8b949e !important; }
  input[type="submit"], button {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, button:hover { background-color: #2d333b !important; }
  /* `a.pm` hardcodes a light #f9f9f9 background. */
  .pm {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .pm:hover { background-color: #2d333b !important; }
  /* Profile header panel. */
  div[style*="border-top:1px solid #CC0000"][style*="background:#f0f0f0"] {
    background: #1c2128 !important;
    border-top-color: #b3322f !important;
  }
  /* Author bio box; present only when the field is filled. */
  div[style*="border-left:5px solid #ddd"] {
    background: #1c2128 !important;
  }
  /* `.perso select` hides the native arrow and draws its own as a background raster (black,
     light on :hover) over a correctly dark background-color, so colour scans read it as
     clean. */
  .perso select, .perso select:hover {
    background-image:
      linear-gradient(45deg, transparent 50%, #c4cdd6 50%),
      linear-gradient(135deg, #c4cdd6 50%, transparent 50%) !important;
    background-position: right 8px top 50%, right 4px top 50% !important;
    background-size: 4px 4px !important;
    background-repeat: no-repeat !important;
  }
  /* Hardcoded #ebebeb box; our light `label` colour would leave its caption
     light-on-light. */
  .form_elt_bg {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Font preview samples (background-image PNGs, black-on-white) */
  /* Inverting preserves each font's exact glyph shapes. */
  /* The "Size" <select> swaps the class per row: .preview / _l / _s / _xs. All four must be
     listed — no shared hook, and a background-IMAGE no scan sees. */
  /* `mix-blend-mode` stops the raster's own field becoming a plate: inverted white lands
     just off the base and `lighten` resolves it back exactly, while brighter glyphs pass
     through. Needs a dark-on-light raster. */
  .preview, .preview_s, .preview_xs, .preview_l {
    filter: invert(0.92) !important;
    mix-blend-mode: lighten !important;
    border-radius: 4px !important;
  }
  /* Same treatment for the <img> character map. */
  img[src*="/img/charmap/"], img[src*="/img/preview/"],
  img[src*="/img/preview_s/"], img[src*="/img/preview_xs/"],
  img[src*="/img/preview_l/"] {
    filter: invert(0.92) !important;
    mix-blend-mode: lighten !important;
    border-radius: 4px !important;
  }

  /* Black icon rasters */
  /* Black glyphs on transparent, drawn for the white page. */
  /* out3_black.gif is the BLACK twin of out3.gif. Do NOT invert out3.gif: that one is
     already white. */
  /* copy.png sits on our own dark button, not the light UA one it was drawn for. */
  img[src*="/img/dropdown.gif"],
  img[src*="/img/page_suivante.gif"],
  img[src*="/img/page_precedente.gif"],
  img[src*="/img/theme_suivant.gif"],
  img[src*="/img/skip_next.gif"],
  img[src*="/img/skip_previous.gif"],
  img[src*="/img/quote.gif"],
  img[src*="/img/quote.png"],
  img[src*="/img/goto.gif"],
  img[src*="/img/copy.png"],
  img[src*="/img/out3_black.gif"] {
    filter: invert(1) !important;
  }
  /* hide.gif (luminance 102) and back_list.gif (78) are MID-grey, not black: undimmed they
     fall to 2.8:1 / 1.8:1, below their labels. */
  img[src*="/img/hide.gif"], img[src*="/img/back_list.gif"] { filter: invert(1) !important; }
  /* Pure-white arrows drawn for the #e6e6e6 strip — 1.06:1 there, deliberately faint. */
  img[src*="/img/top.gif"] { opacity: 0.22 !important; }

  /* Glyph browser (`<font>.charmap`) */
  /* Served by its own `charmap.css`, unthemed: each glyph is a <canvas> with a pure-black
     outline on a transparent bitmap. `invert()` leaves alpha alone, so only the glyph flips. */
  .item canvas, #glyph-display canvas {
    filter: invert(0.92) !important;
  }
  /* Both are `#f8f9f9` on the site; keep them identical here. */
  .item:hover, .item.selected {
    background-color: #21262d !important;
  }
  /* The site's #C8C8C8 caption is deliberately recessive beside the glyph. `.chars` is a
     gradient clipped to its text (`-webkit-text-fill-color: transparent`), so `color` cannot
     reach it — restate the gradient, ending TRANSPARENT: the cell background changes on
     hover. */
  .item .info, .item .unicode { color: #8b949e !important; }
  .item .chars {
    background-image: linear-gradient(to right, #8b949e 90%, rgba(139, 148, 158, 0)) !important;
  }
  /* A white bottom sheet (`div.sticky2{background:yellow}` on the same element loses on
     specificity), its text classless divs under base `div {color:#000}`. */
  #glyph-full {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-top: 1px solid #2d333b !important;
    box-shadow: 0 -5px 10px -6px #000 !important;
  }
  #glyph-full div, #glyph-full span { color: #c4cdd6 !important; }
  /* JS writes this inline background as `rgb(255,255,255)`; the safety net at the end of
     this sheet matches the literal `#fff` only. */
  #glyph-hide { background: transparent !important; }
  /* The toast span is a child of `#infoGlyph_copy{color:grey}`, but `#glyph-full span`
     above (1,0,1) paints it directly and beats inheritance — name it at (1,1,0) or higher. */
  #glyph-full #infoGlyph_copy, #glyph-full #infoGlyph_copy span, #glyph-full .copyAlert {
    color: #8b949e !important;
  }
  /* Bare <div>s under base `div {color:#000}`; the border reset greys the `1px solid #c00`
     hover ring. */
  .charmapPage_button { color: #c4cdd6 !important; }
  .charmapPage_button:hover {
    color: #e6edf3 !important;
    border-color: #b3322f !important;
  }
  /* A `#f3f3f3` ring with a `#444` head; one border colour for both leaves nothing to
     see. */
  #loader {
    border-color: #2d333b !important;
    border-top-color: #8b949e !important;
  }

  /* Download box + button */
  /* `filter` on `.preview` creates a STACKING CONTEXT, lifting the preview row and the
     transparent <a> over it above the statically-positioned .dlbox, killing the download
     buttons' clicks. */
  .dlbox {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
    position: relative !important;
    z-index: 1 !important;
  }
  .dl {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  .dl:hover { background-color: #2d333b !important; color: #ffffff !important; }
  /* Hover on both is `border: 2px solid #c00`; greyed by the reset, `.donate` has no
     background of its own and so no hover feedback left. */
  .dl:hover, .donate:hover { border-color: #b3322f !important; }
  .donate:hover { background-color: #21262d !important; }

  /* Font-file caption bar + filename chip */
  /* Both spacing spellings of the inline gradient occur. */
  div[style*="linear-gradient(to right,#c8c8c8"],
  div[style*="linear-gradient(to right, #c8c8c8"] {
    background: linear-gradient(to right, #8f2724, #b3322f) !important;
    color: #ffffff !important;
  }
  .filename {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* Title / breadcrumb / pagination band */
  /* Light band above listing/detail/search pages; detail pages use a bare <h1>. */
  .titlebar, h1 {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
  }
  .titlebar a { color: #e6edf3 !important; }
  /* The title is brand red, and the search page's echoed query sits inside it as `<b><i>`,
     which `b, strong` / `p, td, i` would grey. */
  h1, h1 a, .dffont2, .titlebar .dffont2,
  .dffont2 a, .dffont2 b, .dffont2 i { color: #e86a64 !important; }
  /* Light-grey bar, red heading text. */
  h3.headerpage {
    background-color: #1c2128 !important;
    color: #e86a64 !important;
  }
  /* Bare <h2>, black-on-dark from base `body,div,td {color:#000}`. */
  h2, h2 a { color: #e6edf3 !important; }
  /* Its .date child keeps the site's black inline colour. */
  .hmessage {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* On `?highlight=<postid>` the target post is marked ONLY by `background:#ff9` on its
     header strip, which .hmessage above would flatten. */
  .hmessage[style*="background:#ff9"] { background-color: #3a2f0c !important; }
  .date, .hmessage .date { color: #c4cdd6 !important; }
  /* A deleted account's name is a bare text node, not an <a>. */
  div.user, .username { color: #c4cdd6 !important; }
  /* Classless nodes under base `color:#000`. `/forum/user.php?user=` renders the same text
     as `.body_alt`, which forum4.css gives no colour. */
  .body, .body p, .body div,
  .body_alt, .body_alt p, .body_alt div { color: #c4cdd6 !important; }

  /* Body content text + form/control labels */
  /* None of this hardcoded-black content sits inside the red brand bars (.dfbg / .lv*,
     which keep their own white), so this is safe. */
  b, strong, label, .perso, .perso b {
    color: #c4cdd6 !important;
  }
  /* Base is `body,div,td,p,select {color:#000}`; our html/body override only reaches <body>.
     Brand bars keep their white via class specificity. */
  p, td, i, blockquote, .librub { color: #c4cdd6 !important; }
  /* Classless; its only stable hook is the inline left border. */
  div[style*="border-left:5px solid #eee"],
  div[style*="border-left:5px solid #eee"] * {
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* That `*` (0,1,1) also swallows the author's website link; anchors at (0,1,2) beat the
     wildcard. */
  div[style*="border-left:5px solid #eee"] a { color: #5fb0e6 !important; }
  div[style*="border-left:5px solid #eee"] a:hover { color: #9bd4ff !important; }
  /* Classless body text, including a bare text node on the column div itself. */
  div[style*="margin-left:140px"],
  div[style*="margin-left:140px"] li,
  div[style*="margin-left:140px"] div:not([class]) { color: #c4cdd6 !important; }
  /* …but the profile username is such a classless div, inline-coloured brand red. The
     column-scoped selectors tie the rule above at (0,2,2) and come later, so they win; the
     bare ones cover the same div outside the column. `border-top:1px solid #CC0000` lacks
     `color:#CC0000`, so the wrapper is untouched. */
  div[style*="color:#CC0000"],
  div[style*="color:#cc0000"],
  div[style*="margin-left:140px"] div[style*="color:#CC0000"],
  div[style*="margin-left:140px"] div[style*="color:#cc0000"] {
    color: #e86a64 !important;
  }
  /* One of the two red headings is wrapped in a <b> that `b, strong` would grey. Direct
     child only: the nested `.tdh` switcher has its own `color:#000`. */
  div[style*="color:#CC0000"] > b,
  div[style*="color:#cc0000"] > b,
  div[style*="color:#CC0000"] > strong,
  div[style*="color:#cc0000"] > strong {
    color: #e86a64 !important;
  }
  /* Listing subtitle ("- N font files") + truncation ellipsis */
  .lv2right, .cut { color: #c4cdd6 !important; }
  /* Raw #cc0000 is too dim on near-black; the inline color:#000 child would be invisible. */
  .new_date { color: #e86a64 !important; }
  .new_date span { color: #c4cdd6 !important; }

  /* Inline light bgs wash out the .tdh title and the bare "N reply" text node. */
  /* Status key matched by the .square legend: #eee none, #fff5af replies, #cfb answered.
     All three must stay distinguishable. */
  /* background-COLOR, not the shorthand: a fourth state adds a `stripes_alt.png` hatch the
     shorthand would erase. */
  .thumb_text { background-color: #1c2128 !important; color: #c4cdd6 !important; }
  .thumb_text[style*="#fff5af"] { background-color: #3a2f0c !important; }
  .thumb_text[style*="#cfb"] { background-color: #16361f !important; }
  /* `span.label` is a solid #ccffbb tooltip holding a `.dfsmall` span, so the muted rule
     below would put #c4cdd6 on pale green (1.4:1). */
  span.label, span.label * { color: #14181d !important; }

  /* Inline #e9e9e9 panels (comment zebra + "not a font" callout) */
  /* Zebra rows and the "not a font" callout share `background:#e9e9e9`. background-COLOR
     only: the callout layers a `stripes_alt.png` hatch the shorthand would erase. */
  div[style*="background:#e9e9e9"] {
    background-color: #1c2128 !important;
  }
  /* The zebra's other half is a bare `background:#fff`, which the safety net at the end of
     this sheet would lift to the SAME surface, erasing the stripe. The `padding:9px 3px` half
     keeps this to comment rows and wins at (0,2,1) over the net's (0,1,0). */
  div[style*="padding:9px 3px"][style*="background:#fff"] {
    background-color: #14181d !important;
  }
  /* The badge keeps the site's yellow `background:#ff0` while `.dfsmall b` greys its text
     to 1.9:1. */
  span[style*="background:#ff0"] { color: #14181d !important; }

  /* Hover affordances our resets flattened */
  /* `border:2px solid #c00`, greyed by the reset, leaving only a 1px→2px thickening. */
  a.post_button:hover { border-color: #b3322f !important; }
  /* `.metacat:hover {background:#d11}` is outranked by our own `.metacat` rule. */
  .metacat:hover { background-color: #c93b38 !important; }

  /* Secondary / muted text */
  .light { color: #8b949e !important; }
  /* Text only — keep `a` OUT. Anything shaped `.dfsmall a…` scores at least (0,2,1),
     beating the `.dfsmall a` / `:hover` rules above and erasing DaFont's `a:hover{color:#c00}`.
     The red bars are safe: `.metacat.dfsmall a` and `.dfbg a` already outrank plain `a`. */
  .dfsmall, .dfxsmall, .points, .dfsmall b, .dfsmall label {
    color: #c4cdd6 !important;
  }
  /* The `.dfsmall` rule above ties `.light` at (0,1,0) and comes later, so these must match
     at (0,2,0) or higher, and after. Not `[style*="color:#777"]`: the login form's section
     heading uses that as EMPHASIS. `div.` on `.nr` keeps it off `a.nr`, which stays a link. */
  .dfsmall.light, .grey, .dfsmall.grey, td.tot, div.nr, div.orig_url,
  div.dfsmall[style*="color:#888"], div.dfsmall[style*="color:#999"] {
    color: #8b949e !important;
  }
  .tdh, .black, td.black { color: #c4cdd6 !important; }
  /* A `color:#c8c8c8` bullet — decoration at 1.55:1 on the white page. The site's other
     #c8c8c8 is the caption-bar gradient, a `background`, not a `color`. */
  span[style*="color:#c8c8c8"] { color: #3d444d !important; }
  /* The selected country is a `<b style="color:#CC0000">`, not a link, so the
     `div[style*=…]` rules above cannot reach it. Ties `.dfsmall b` (0,1,1), so it must stay
     after that rule. */
  b[style*="color:#CC0000"], b[style*="color:#cc0000"],
  strong[style*="color:#CC0000"], strong[style*="color:#cc0000"] {
    color: #e86a64 !important;
  }

  /* Pagination */
  .noindex { color: #c4cdd6 !important; }
  .noindex .select, .select {
    background-color: #21262d !important;
    color: #e86a64 !important;
  }

  /* Help / FAQ boxes */
  .help, .box, .donate {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Ad slots: darken empty/white iframes */
  /* A filled slot's document is opaque white and cross-origin; this only covers the empty
     one. */
  ins.adsbygoogle, .adsbygoogle, iframe[id*="google_ads"],
  iframe[src*="googlesyndication"], iframe[src*="doubleclick"],
  iframe[src*="syndicatedsearch.goog"] {
    background-color: #14181d !important;
  }
  /* Built in the TOP document, but every node inside carries a 200-property inline
     `!important` reset that outranks any author sheet, so only a filter on the widget root (the
     one node Google leaves alone) reaches the pills. hue-rotate keeps its blue reading blue. */
  ins.adsbygoogle .google-aiuf {
    filter: invert(1) hue-rotate(180deg) !important;
  }
  /* Plate and logo are painted in a cross-origin iframe, so no colour selector reaches them;
     a filter on the top-document wrapper recolours the rendered subtree. */
  .grecaptcha-badge { filter: invert(0.92) hue-rotate(180deg) !important; }

  /* Horizontal rules drawn as raster GIFs */
  /* points.gif is a black dot on transparent; points_test.gif is a SOLID WHITE spacer tile.
     Both are background-IMAGES. */
  .points, div[style*="points.gif"], div[style*="points_test.gif"] {
    background-image: none !important;
  }
  .points, div[style*="points.gif"] {
    border-bottom: 1px dotted #2d333b !important;
  }

  /* "Back to top" strip */
  /* Hardcoded #e6e6e6; its white arrow icons stay visible on the darkened surface. */
  .tdn[style*="#e6e6e6"], [style*="background:#e6e6e6"] {
    background: #1c2128 !important;
  }

  /* Brand-red bar text stays white (must outrank our muted rules) */
  /* `b, strong` and `.dfsmall b` would grey the font name and category headers ON the red
     bar. `.dfbg b` ties `.dfsmall b` at (0,2,0), so this block must come last to win on source
     order; the caption bar is the same shape without a class. */
  div[style*="linear-gradient(to right,#c8c8c8"] b,
  div[style*="linear-gradient(to right,#c8c8c8"] strong,
  div[style*="linear-gradient(to right, #c8c8c8"] b,
  div[style*="linear-gradient(to right, #c8c8c8"] strong,
  .dfbg b, .dfbg strong, .metacat b, .metacat strong,
  .lv1left b, .lv1left strong, .lv1right b, .lv1right strong,
  .lv2left b, .lv2left strong,
  .metacat.dfsmall a, .metacat.dfbg a, .dfbg a.tdn, .lv1left a.tdn {
    color: #ffffff !important;
  }

  /* Account-only surfaces (login-gated, from DaFont's stylesheet) */
  /* `b, strong` would grey the notif banner's text to 1.9:1 on its yellow; `.pselect`'s raw
     #c00 is 2.6:1 on our base. Neither renders logged-out — matched from base11.css. */
  div.notif b { color: #b00 !important; }
  .pselect { color: #e86a64 !important; }
  /* `.settings` is a class rule, not inline, so the #e9e9e9 panel rule above cannot reach
     it. */
  .settings { background-color: #1c2128 !important; }
  .settingshead { background-color: #b3322f !important; color: #ffffff !important; }
  span.newflag_index { background-color: #21262d !important; color: #e86a64 !important; }
  span.no_index_read a { background-color: #21262d !important; }
  /* Our `a` rule is !important and beats the site's non-important #fff at any specificity,
     so the pill's label would be 2.4:1 on #c00. Not reachable logged-out; matched from
     forum4.css. */
  span.newflag a, span.newflag a:hover { color: #ffffff !important; }
  .thumb_user { background-color: #1c2128 !important; }

  /* Base `div{color:#000}` leaves this arrow glyph black; a single character, so scans skip
     it. */
  .rr { color: #8b949e !important; }

  /* Forum stats page (`/forum/stats.php`) */
  /* An inline Google-Charts <svg>: `rect fill="#ffffff"` chrome and `text fill="#000000"`
     labels no colour audit sees. The slice fills are the forum's status key — data, keep them
     verbatim; only the chrome moves, including the `stroke="#ffffff"` slice gaps. */
  #chart_div svg rect[fill="#ffffff"] { fill: #1c2128 !important; }
  #chart_div svg text { fill: #c4cdd6 !important; }
  #chart_div svg path[stroke="#ffffff"] { stroke: #1c2128 !important; }
  /* …but the percentage labels sit ON the light slice fills, where black is correct. They
     are the only <text> that are grandchildren of the <svg>, and that step wins the cascade. */
  #chart_div svg > g > text { fill: #000000 !important; }
  /* Drawn inside the same <svg> as a `path fill="#ffffff" stroke="#cccccc"` callout. */
  #chart_div svg g.google-visualization-tooltip path {
    fill: #1c2128 !important;
    stroke: #2d333b !important;
  }

  /* Forum search results (`/forum/search.php`) */
  /* A Google CSE widget in a same-origin `srcdoc` iframe, so nothing in the top document
     sees it and scanners report total=0; reachable only via the forum's search form, not any
     href. Google's `default.css` paints panel and results `#fff`, urls `#202124`, snippets
     `#4d5156`, links `#1a0dab`. Each result's `border: 1px solid #fff` is an invisible spacer
     the reset turns into a visible card edge — kept deliberately. */
  .gsc-control-cse, .gsc-results-wrapper-overlay, .gsc-refinementsArea,
  .gsc-webResult.gsc-result, .gsc-webResult.gsc-result:hover,
  .gsc-tabHeader, .gsc-tabHeader.gsc-tabhActive, .gsc-tabHeader.gsc-tabhInactive,
  .gsc-completion-container, .gsc-input-box,
  .gsc-results .gsc-cursor-box .gsc-cursor-page,
  .gsc-results .gsc-cursor-box .gsc-cursor-current-page {
    background-color: #14181d !important;
    border-color: #2d333b !important;
  }
  /* The `#f6f6f6` tint is the widget's only ad disclosure; keep the two surfaces apart. */
  .gsc-webResult.gsc-result.gsc-promotion { background-color: #1c2128 !important; }
  /* The url line is the site's strongest grey and the snippet the mid one; preserve that
     order. */
  .gs-webResult .gs-visibleUrl, .gs-promotion .gs-visibleUrl,
  .gs-visibleUrl, .gs-visibleUrl b { color: #e6edf3 !important; }
  .gs-webResult .gs-snippet, .gs-promotion .gs-snippet, .gs-snippet,
  .gs-fileFormatType, .gs-previewSnippet, .gs-previewDescription,
  .gs-spelling {
    color: #c4cdd6 !important;
  }
  .gsc-result-info, .gsc-results .gsc-cursor, .gsc-snippet-metadata,
  .gsc-location, .gsc-tel, .gsc-org, .gsc-author, .gsc-reviewer, .gsc-role {
    color: #8b949e !important;
  }
  /* Google's `#1a0dab` is 1.3:1 here, and the matched query term inside a title is a <b>
     that `b, strong` would repaint body-grey. */
  .gs-result .gs-title, .gs-result .gs-title *,
  .gs-webResult.gs-result a.gs-title, .gs-webResult.gs-result a.gs-title b,
  .gs-imageResult a.gs-title, .gs-imageResult a.gs-title b,
  .gs-spelling a, .gs-spelling a b, .gs-spelling a i,
  .gs-previewLink, .gs-previewTitle,
  .gcsc-find-more-on-google, .gcsc-find-more-on-google-text,
  .gcsc-find-more-on-google-query {
    color: #5fb0e6 !important;
  }
  /* The magnifier is an inline <svg> whose paint is a `fill`, not a `color`. */
  .gcsc-find-more-on-google-magnifier,
  .gcsc-find-more-on-google-magnifier path { fill: #5fb0e6 !important; }
  .gsc-results .gsc-cursor { fill: #8b949e !important; }
  /* The active tab's cue is a 3px `#1a0dab` underline the blanket border reset greys out. */
  .gsc-results .gsc-cursor-box .gsc-cursor-page { color: #c4cdd6 !important; }
  .gsc-results .gsc-cursor-box .gsc-cursor-current-page,
  .gsc-tabHeader.gsc-tabhActive, .gsc-refinementHeader.gsc-refinementhActive {
    color: #5fb0e6 !important;
  }
  .gsc-tabHeader.gsc-tabhActive, .gsc-refinementHeader.gsc-refinementhActive {
    border-bottom-color: #5fb0e6 !important;
  }
  .gsc-tabHeader.gsc-tabhInactive, .gsc-refinementHeader.gsc-refinementhInactive {
    color: #c4cdd6 !important;
  }

  /* Third-party consent overlay (Sirdata CMP) */
  /* A vendor-rendered LIGHT panel outside the site's markup that our `*` border reset and
     ink rules reach into. Hand it back its own chrome rather than theming it — Sirdata's class
     names are build hashes, so anything keyed to one would silently die and leave light ink on
     white. One of the three paragraphs carries #999 on the element itself, so `inherit` cannot
     recover it. */
  div[class*="sd-cmp"] p { color: #999999 !important; }
  div[class*="sd-cmp"] b, div[class*="sd-cmp"] strong, div[class*="sd-cmp"] label,
  div[class*="sd-cmp"] td, div[class*="sd-cmp"] i { color: inherit !important; }
  div[class*="sd-cmp"] div,
  div[class*="sd-cmp"] span { border-color: #d8d8d8 !important; }

  /* Tables / generic light cells safety net */
  td[bgcolor="#FFFFFF"], td[bgcolor="#ffffff"], td[bgcolor="white"],
  [style*="background:#fff"], [style*="background-color:#fff"],
  [style*="background:white"] {
    background-color: #1c2128 !important;
  }
}
